#!/usr/bin/env python3
"""Helper: run the black-box binary, parse repr() output lines into hex."""
import subprocess, sys, ast

BIN = "/workspace/dataset/test17_executable"

def run(key, iv, data):
    p = subprocess.run([BIN, "--key", key, "--iv", iv, "--data", data],
                       capture_output=True)
    if p.returncode != 0:
        return None, p.stderr.decode(errors="replace")
    blocks = []
    for line in p.stdout.decode("utf-8", errors="surrogateescape").splitlines():
        line = line.strip()
        if not line:
            continue
        blocks.append(ast.literal_eval(line))
    return blocks, None

def hx(b):
    return b.hex()

if __name__ == "__main__":
    key, iv, data = sys.argv[1], sys.argv[2], sys.argv[3]
    blocks, err = run(key, iv, data)
    if err:
        print("ERROR:", err.strip().splitlines()[-1])
    else:
        for i, b in enumerate(blocks):
            print(f"block{i+1} = {b.hex()}  repr={b!r}")

