#!/usr/bin/env python3
"""Find a ciphertext block that is a valid UTF-8, NUL-free byte string, so it can
be passed as --iv via bash $'\\xNN' escapes (argv is decoded UTF-8 then re-encoded
UTF-8, so only valid-UTF-8 non-NUL byte strings survive the round trip)."""
import subprocess, ast, random, string, sys
from concurrent.futures import ProcessPoolExecutor

BIN = "/workspace/dataset/test17_executable"
ALPHA = string.ascii_letters + string.digits + "-_.,:;=+*/?@#%^&()[]{}<>|~ "
NBLK = 64

def typable(b):
    if b"\x00" in b:
        return False
    try:
        b.decode("utf-8")
        return True
    except UnicodeDecodeError:
        return False

def trial(arg):
    seed, keylen = arg
    rnd = random.Random((seed, keylen))
    key = "".join(rnd.choice(ALPHA) for _ in range(keylen))
    iv = "".join(rnd.choice(ALPHA) for _ in range(16))
    data = "".join(rnd.choice(ALPHA) for _ in range(16 * NBLK))
    p = subprocess.run([BIN, "--key", key, "--iv", iv, "--data", data], capture_output=True)
    if p.returncode != 0:
        return None
    blocks = [ast.literal_eval(l) for l in
              p.stdout.decode("utf-8", "surrogateescape").splitlines() if l.strip()]
    # want C_1 typable so the source run can be a compact 2-block run
    if typable(blocks[0]):
        return (keylen, key, iv, data[:32], blocks[0].hex(), blocks[1].hex())
    return None

if __name__ == "__main__":
    for keylen in (24, 32):
        found = None
        with ProcessPoolExecutor(max_workers=12) as ex:
            args = [(s, keylen) for s in range(60000)]
            for r in ex.map(trial, args, chunksize=20):
                if r:
                    found = r
                    break
        print(repr(found), flush=True)
